#include <cmath>
#include <cassert>
#include <iostream>

template<int n> struct vec {
 double data[n] = {0};
 double& operator[](const int i) { assert(i>=0 && i<n); return data[i]; }
 double operator[](const int i) const { assert(i>=0 && i<n); return data[i]; }
};

template<> struct vec<2> {
 double x = 0, y = 0;
 double& operator[](const int i) { assert(i>=0 && i<2); return i ? y : x; }
 double operator[](const int i) const { assert(i>=0 && i<2); return i ? y : x; }
};

template<> struct vec<3> {
 double x = 0, y = 0, z = 0;
 double& operator[](const int i) { assert(i>=0 && i<3); return i ? (1==i ? y : z) : x; }
 double operator[](const int i) const { assert(i>=0 && i<3); return i ? (1==i ? y : z) : x; }
};

template<int nrows,int ncols> struct mat {
 vec<ncols> rows[nrows] = {{}};
 vec<ncols>& operator[] (const int idx) { assert(idx>=0 && idx<nrows); return rows[idx]; }
 const vec<ncols>& operator[] (const int idx) const { assert(idx>=0 && idx<nrows); return rows[idx]; }
};

typedef mat<3,3> mat3;

double mat3_cofactor(const mat3& m, const int row, const int col) {
    // Calculate the minor (determinant of 2x2 submatrix)
    // by excluding the given row and column

    int r0 = (row + 1) % 3;
    int r1 = (row + 2) % 3;
    int c0 = (col + 1) % 3;
    int c1 = (col + 2) % 3;

    // Determinant of 2x2 matrix:
    // | a b |
    // | c d | = a*d - b*c
    double a = m[r0][c0];
    double b = m[r0][c1];
    double c = m[r1][c0];
    double d = m[r1][c1];

    double minor = a * d - b * c;

    // Cofactor = (-1)^(row+col) * minor
    return ((row + col) % 2 == 0) ? minor : -minor;
}

// Test
int main() {
    mat3 m;
    m[0][0] = 1; m[0][1] = 2; m[0][2] = 3;
    m[1][0] = 4; m[1][1] = 5; m[1][2] = 6;
    m[2][0] = 7; m[2][1] = 8; m[2][2] = 9;

    // Test cofactor(0,0): (-1)^(0+0) * det([[5,6],[8,9]]) = 1 * (5*9 - 6*8) = 1 * (45-48) = -3
    double c00 = mat3_cofactor(m, 0, 0);
    std::cout << "cofactor(0,0) = " << c00 << " (expected -3)" << std::endl;
    assert(std::abs(c00 - (-3.0)) < 1e-9);

    // Test cofactor(0,1): (-1)^(0+1) * det([[4,6],[7,9]]) = -1 * (4*9 - 6*7) = -1 * (36-42) = 6
    double c01 = mat3_cofactor(m, 0, 1);
    std::cout << "cofactor(0,1) = " << c01 << " (expected 6)" << std::endl;
    assert(std::abs(c01 - 6.0) < 1e-9);

    // Test cofactor(1,1): (-1)^(1+1) * det([[1,3],[7,9]]) = 1 * (1*9 - 3*7) = 1 * (9-21) = -12
    double c11 = mat3_cofactor(m, 1, 1);
    std::cout << "cofactor(1,1) = " << c11 << " (expected -12)" << std::endl;
    assert(std::abs(c11 - (-12.0)) < 1e-9);

    std::cout << "All tests passed!" << std::endl;
    return 0;
}

